<script lang="ts" setup>import { ref, computed, watch } from "vue"
import { useClipboard } from "@vueuse/core"
import { scv, cx } from "css-variants"
import RLVButton from "@rimelight/ui/components/vue/RLVButton.vue"
import RLVCheckbox from "@rimelight/ui/components/vue/RLVCheckbox.vue"
import RLVInput from "@rimelight/ui/components/vue/RLVInput.vue"
import RLVFormField from "@rimelight/ui/components/vue/RLVFormField.vue"
import { useRC, useAssetManagement, useAuth, useToast } from "@/composables"/* region Props */export interface AssetManagerModalProps {  rc?: {    root?: string  }  selectionMode?: boolean}const { rc: rcProp, selectionMode = false } = defineProps<AssetManagerModalProps>()const { rc } = useRC("AssetManagerModal", rcProp)const { copy } = useClipboard()const toast = useToast()const t = (key: string, data?: any) => {  const keys: Record<string, string> = {    "modals.assetManager.header.title": "Asset Manager",    "modals.assetManager.header.description": "Manage your organization's assets and folders.",    "modals.assetManager.empty.title": "No assets found",    "modals.assetManager.empty.description":      "Drag and drop files here or click the upload button to add your first asset.",    "modals.assetManager.upload.dropzone_label": "Upload assets",    "modals.assetManager.upload.dropzone_description": "Drop files here or click to select",    "modals.assetManager.upload.select_button": "Select Files",    "modals.assetManager.item.folder_label": "Folder",    "modals.assetManager.item.copy_url": "Copy URL",    "modals.assetManager.item.copy_url_success": "URL copied successfully",    "modals.assetManager.item.copy_url_failed": "Failed to copy URL",    "modals.assetManager.item.last_modified": "Last modified: {date}",    "modals.newFolder.title": "New Folder",    "modals.newFolder.description": "Create a new subfolder in the current directory.",    "modals.newFolder.label": "Folder Path: {path}",    "modals.newFolder.placeholder": "Folder Name",    "modals.newFolder.cancel_button": "Cancel",    "modals.newFolder.create_button": "Create",    "modals.move.title": "Move or Rename Asset",    "modals.move.name_label": "New Name",    "modals.move.folder_label": "Target Folder",    "modals.move.current_location": "Current location: {path}",    "modals.move.cancel_button": "Cancel",    "modals.move.move_button": "Move",    "modals.upload.title": "Upload Assets",    "modals.upload.filename_label": "File Name",    "modals.upload.folder_label": "Upload Destination Folder",    "modals.upload.cancel_button": "Cancel",    "modals.upload.upload_button": "Upload",    "modals.upload.multiple_files_warning.title": "Uploading multiple files",    "modals.upload.multiple_files_warning.description":      "You cannot rename multiple files during upload.",    "modals.upload.files_selected": "{count} files selected",    "modals.assetManager.toolbar.selected_count": "{count} selected",    "modals.assetManager.toolbar.items_count": "{count} items",    "modals.assetManager.actions.new_subfolder": "New Subfolder",    "modals.assetManager.upload.add_asset_button": "Upload Asset"  }  let val = keys[key] || key  if (data) {    for (const [k, v] of Object.entries(data)) {      val = val.replace(`{${k}}`, String(v))    }  }  return val}/* endregion *//* region Emits */export interface AssetManagerModalEmits {  close: []  select: [key: string]}const emit = defineEmits<AssetManagerModalEmits>()/* endregion *//* region Styles */const assetManagerStyles = scv({  slots: [    "root",    "main",    "sidebar",    "sidebarContent",    "sidebarFooter",    "content",    "toolbar",    "grid",    "item",    "preview",    "previewImage",    "itemInfo",    "itemLabel",    "itemSize",    "actions"  ],  base: {    root: "flex flex-col h-[70vh] w-full overflow-hidden",    main: "flex flex-1 min-h-0 overflow-hidden",    sidebar:      "w-64 border-r border-neutral-200 dark:border-neutral-800 flex flex-col overflow-hidden bg-neutral-50/30 dark:bg-neutral-900/30",    sidebarContent: "flex-1 overflow-y-auto p-4",    sidebarFooter:      "p-4 border-t border-neutral-200 dark:border-neutral-800 bg-neutral-50/50 dark:bg-neutral-900/50",    content: "flex-1 flex flex-col min-w-0 overflow-hidden",    toolbar:      "p-4 border-b border-neutral-200 dark:border-neutral-800 flex items-center justify-between bg-neutral-50/10 dark:bg-neutral-900/10 shrink-0",    grid: "grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 p-4 overflow-y-auto flex-1 min-h-0 items-start content-start",    item: "group relative aspect-square flex flex-col gap-2 p-3 rounded-xl border border-neutral-200 dark:border-neutral-800 hover:border-primary-500 transition-colors bg-neutral-50/50 dark:bg-neutral-900 overflow-hidden",    preview:      "flex-1 min-h-0 w-full rounded-lg overflow-hidden bg-neutral-100 dark:bg-neutral-800 flex items-center justify-center relative",    previewImage: "w-full h-full object-contain",    itemInfo: "flex flex-col gap-0.5 overflow-hidden shrink-0",    itemLabel:      "text-[11px] font-semibold truncate leading-tight text-neutral-800 dark:text-neutral-200",    itemSize: "text-[10px] text-neutral-400 dark:text-neutral-500",    actions:      "absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity bg-black/60 p-1 rounded-lg backdrop-blur-sm"  }})const styles = computed(() => {  const resolved = assetManagerStyles()  const result: Record<string, string> = {}  for (const [slot, value] of Object.entries(resolved)) {    result[slot] = cx(value, (rc.value as Record<string, string>)[slot])  }  return result})/* endregion *//* region State */interface TreeItemExtended {  label: string  fullPath: string  icon?: string  defaultExpanded?: boolean  children?: TreeItemExtended[]}const open = defineModel<boolean>("open", { default: false })const { permissions: authPermissions } = useAuth()const {  assets,  status,  selectedPath,  selectedKeys,  localFolders,  isProcessing,  refresh,  uploadAsset,  deleteAsset,  moveAsset,  batchDelete,  downloadAsset,  addLocalFolder,  splitFilename} = useAssetManagement()const isDragging = ref(false)const draggedItem = ref<any>(null)const dropTarget = ref<any>(null)const breadcrumbs = computed(() => {  const crumbs = [{ label: "Root", path: "" }]  if (selectedPath.value) {    const parts = selectedPath.value.split("/")    let currentPath = ""    parts.forEach((part) => {      currentPath += (currentPath ? "/" : "") + part      crumbs.push({ label: part, path: currentPath })    })  }  return crumbs})// --- New Folder State ---const showNewFolderModal = ref(false)const newFolderName = ref("")// --- Upload State ---const showUploadModal = ref(false)const pendingFiles = ref<File[]>([])const uploadFileBasename = ref("")const uploadFileExtension = ref("")const uploadTargetFolder = ref("")// --- Move/Rename State ---const showMoveModal = ref(false)const movingAsset = ref<any>(null)const moveTargetBasename = ref("")const moveTargetFolder = ref("")const fileInput = ref<HTMLInputElement | null>(null)const modalUploadTargetValue = computed({  get: () => findNodeByPath(uploadTargetFolder.value, treeItems.value) || treeItems.value[0],  set: (val: any) => {    const selected = Array.isArray(val) ? val[0] : val    if (!selected) return    const path = typeof selected === "object" ? (selected.fullPath ?? "") : selected    uploadTargetFolder.value = path === "Root" ? "" : path  }})const modalMoveTargetValue = computed({  get: () => findNodeByPath(moveTargetFolder.value, treeItems.value) || treeItems.value[0],  set: (val: any) => {    const selected = Array.isArray(val) ? val[0] : val    if (!selected) return    const path = typeof selected === "object" ? (selected.fullPath ?? "") : selected    moveTargetFolder.value = path === "Root" ? "" : path  }})const treeItems = computed<TreeItemExtended[]>(() => {  const rootNode: TreeItemExtended[] = [    {      label: "Root",      fullPath: "",      icon: "i-lucide-home",      defaultExpanded: true,      children: []    }  ]  if (!assets.value) return rootNode  const foldersSet = new Set<string>()  assets.value.forEach((asset) => {    const parts = asset.key.split("/")    if (parts.length > 1) {      let currentPath = ""      for (let i = 0; i < parts.length - 1; i++) {        currentPath += (currentPath ? "/" : "") + parts[i]        if (currentPath) foldersSet.add(currentPath)      }    }  })  localFolders.value.forEach((f) => {    if (f && typeof f === "string") foldersSet.add(f)  })  const sortedFolders = Array.from(foldersSet).toSorted()  const findOrCreateNode = (    parent: TreeItemExtended[],    path: string,    label: string  ): TreeItemExtended => {    let node = parent.find((n) => n.label === label)    if (!node) {      node = {        label,        fullPath: path,        children: []      }      parent.push(node)    }    return node  }  sortedFolders.forEach((folderPath) => {    if (typeof folderPath !== "string") return    const parts = folderPath.split("/")    const first = rootNode[0]    if (!first || !first.children) return    let currentLevel = first.children as TreeItemExtended[]    let currentFullPath = ""    parts.forEach((part) => {      currentFullPath += (currentFullPath ? "/" : "") + part      const node = findOrCreateNode(currentLevel, currentFullPath, part)      currentLevel = node.children as TreeItemExtended[]    })  })  return rootNode})const currentNode = computed(() => {  return findNodeByPath(selectedPath.value, treeItems.value) || treeItems.value[0]})const activeTreeValue = computed({  get: () => currentNode.value,  set: (val: any) => {    const selected = Array.isArray(val) ? val[0] : val    if (!selected) return    const path = typeof selected === "object" ? (selected.fullPath ?? "") : selected    selectedPath.value = path === "Root" ? "" : path  }})const gridItems = computed(() => {  const folders =    currentNode.value?.children?.map((n) => ({      key: n.fullPath,      label: n.label,      type: "folder" as const    })) || []  const assetsInDir =    assets.value      ?.filter((asset) => {        const parts = asset.key.split("/")        const assetPath = parts.slice(0, -1).join("/")        return assetPath === selectedPath.value      })      .map((a) => ({ ...a, type: "asset" as const })) || []  return [...folders, ...assetsInDir]})/* endregion *//* region Lifecycle */watch(open, (isOpen) => {  if (isOpen) refresh()})/* endregion *//* region Logic */function findNodeByPath(path: string, nodes: TreeItemExtended[]): TreeItemExtended | undefined {  const normalizedPath = path === "/" || path === "Root" || !path ? "" : path  for (const node of nodes) {    if (node.fullPath === normalizedPath) return node    if (node.children?.length) {      const found = findNodeByPath(normalizedPath, node.children)      if (found) return found    }  }  return undefined}function triggerFilePicker() {  fileInput.value?.click()}function handleFileSelected(event: Event) {  const filesInput = (event.target as HTMLInputElement).files  if (!filesInput) return  const filesList = Array.from(filesInput)  if (filesList.length > 0) {    pendingFiles.value = filesList    uploadTargetFolder.value = selectedPath.value    if (filesList.length === 1) {      const { basename, extension } = splitFilename(filesList[0].name)      uploadFileBasename.value = basename      uploadFileExtension.value = extension    } else {      uploadFileBasename.value = ""      uploadFileExtension.value = ""    }    showUploadModal.value = true  }}async function performUpload() {  if (pendingFiles.value.length === 0) return  const filesToUpload = pendingFiles.value.length === 1 ? pendingFiles.value[0] : pendingFiles.value  const success = await uploadAsset(    filesToUpload,    uploadTargetFolder.value,    pendingFiles.value.length === 1 ? uploadFileBasename.value : undefined  )  if (success) {    showUploadModal.value = false    pendingFiles.value = []    uploadFileBasename.value = ""    uploadFileExtension.value = ""  }}function triggerNewFolder() {  newFolderName.value = ""  showNewFolderModal.value = true}function confirmNewFolder() {  const newPath = addLocalFolder(newFolderName.value, selectedPath.value)  if (newPath) {    selectedPath.value = newPath    showNewFolderModal.value = false    newFolderName.value = ""  }}function triggerMove(asset: any) {  movingAsset.value = asset  const parts = asset.key.split("/")  const fullFilename = parts.pop()!  const lastDot = fullFilename.lastIndexOf(".")  moveTargetFolder.value = parts.join("/")  if (lastDot === -1) {    moveTargetBasename.value = fullFilename  } else {    moveTargetBasename.value = fullFilename.substring(0, lastDot)  }  showMoveModal.value = true}async function performMove() {  if (!movingAsset.value || !moveTargetBasename.value) return  const success = await moveAsset(    movingAsset.value.key,    moveTargetFolder.value,    moveTargetBasename.value  )  if (success) {    showMoveModal.value = false  }}function toggleSelection(key: string) {  const index = selectedKeys.value.indexOf(key)  if (index > -1) {    selectedKeys.value = selectedKeys.value.filter((k) => k !== key)  } else {    selectedKeys.value = [...selectedKeys.value, key]  }}function handleDragStart(itemObj: any, event: DragEvent) {  isDragging.value = true  draggedItem.value = itemObj  if (event.dataTransfer) {    event.dataTransfer.effectAllowed = "move"  }}function handleDragOverFolder(itemObj: any, event: DragEvent) {  if (itemObj.type === "folder" && draggedItem.value?.type === "asset") {    dropTarget.value = itemObj  }}async function handleDropOnFolder(itemObj: any, event: DragEvent) {  const asset = draggedItem.value  const folder = itemObj  if (asset && folder && asset.type === "asset" && folder.type === "folder") {    const fileName = asset.key.split("/").pop() || ""    const lastDot = fileName.lastIndexOf(".")    const basename = lastDot === -1 ? fileName : fileName.substring(0, lastDot)    await moveAsset(asset.key, folder.key, basename)  }  isDragging.value = false  draggedItem.value = null  dropTarget.value = null}function isImage(contentType?: string, key?: string) {  if (contentType?.startsWith("image/")) return true  const ext = key?.split(".").pop()?.toLowerCase()  return ["jpg", "jpeg", "png", "gif", "webp", "svg"].includes(ext || "")}function formatSize(bytes: number) {  if (bytes === 0) return "0 B"  const k = 1024  const sizes = ["B", "KB", "MB", "GB"]  const i = Math.floor(Math.log(bytes) / Math.log(k))  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i]}function formatDate(date: string | Date) {  if (!date) return ""  const d = new Date(date)  const day = String(d.getDate()).padStart(2, "0")  const month = String(d.getMonth() + 1).padStart(2, "0")  const year = d.getFullYear()  const hours = String(d.getHours()).padStart(2, "0")  const minutes = String(d.getMinutes()).padStart(2, "0")  const dateStr = `${day}/${month}/${year} ${hours}:${minutes}`  return t("modals.assetManager.item.last_modified", { date: dateStr })}function getAssetUrl(key: string): string {  const encodedKey = key.split("/").map(encodeURIComponent).join("/")  if (typeof window === "undefined") return `/api/assets/${encodedKey}`  return `${window.location.origin}/api/assets/${encodedKey}`}async function copyAssetUrl(key: string) {  try {    const url = getAssetUrl(key)    await copy(url)    toast.add({      title: t("modals.assetManager.item.copy_url_success"),      description: url,      color: "success"    })  } catch {    toast.add({      title: t("modals.assetManager.item.copy_url_failed"),      color: "error"    })  }}/* endregion */defineOptions({  name: "AssetManagerModal"})</script><template>  <teleport to="body">    <!-- Outer container -->    <div      v-if="open"      class="fixed inset-0 z-50 overflow-hidden flex items-center justify-center p-4"      role="dialog"      aria-modal="true"    >      <!-- Overlay Backdrop -->      <div        class="absolute inset-0 bg-neutral-900/60 backdrop-blur-sm transition-opacity duration-300"        @click="open = false"      />      <!-- Content Panel -->      <div        class="bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border border-neutral-200 dark:border-neutral-800 w-full max-w-6xl max-h-[90vh] flex flex-col overflow-hidden relative z-10 transition-transform duration-300"      >        <!-- Header -->        <div          class="px-6 py-5 border-b border-neutral-100 dark:border-neutral-800 flex items-center justify-between shrink-0"        >          <div>            <h2 class="text-lg font-semibold text-neutral-900 dark:text-white">              {{ t("modals.assetManager.header.title") }}            </h2>            <p class="text-xs text-neutral-500">              {{ t("modals.assetManager.header.description") }}            </p>          </div>          <RLVButton            color="neutral"            variant="link"            square            icon="i-lucide-x"            class="rounded-full"            @click="open = false"          />        </div>        <!-- Body -->        <div class="flex-1 overflow-hidden min-h-0 flex flex-row">          <!-- Sidebar -->          <div :class="styles.sidebar">            <div :class="styles.sidebarContent">              <!-- Recursive tree structure -->              <div class="flex flex-col gap-1">                <button                  v-for="node in treeItems"                  :key="node.fullPath"                  class="w-full text-left px-3 py-2 rounded-lg text-sm transition-colors flex items-center gap-2"                  :class="[                    selectedPath === node.fullPath                      ? 'bg-primary-500 text-white font-medium'                      : 'hover:bg-neutral-100 dark:hover:bg-neutral-800 text-neutral-700 dark:text-neutral-300'                  ]"                  @click="selectedPath = node.fullPath"                >                  <span class="i-lucide-home size-4 shrink-0" />                  <span>{{ node.label }}</span>                </button>                <div v-if="treeItems[0]?.children?.length" class="pl-4 flex flex-col gap-1 mt-1">                  <button                    v-for="subNode in treeItems[0].children"                    :key="subNode.fullPath"                    class="w-full text-left px-3 py-1.5 rounded-lg text-sm transition-colors flex items-center gap-2"                    :class="[                      selectedPath === subNode.fullPath                        ? 'bg-primary-500 text-white font-medium'                        : 'hover:bg-neutral-100 dark:hover:bg-neutral-800 text-neutral-700 dark:text-neutral-300'                    ]"                    @click="selectedPath = subNode.fullPath"                  >                    <span class="i-lucide-folder size-4 shrink-0" />                    <span class="truncate">{{ subNode.label }}</span>                  </button>                </div>              </div>            </div>          </div>          <!-- Content -->          <div :class="styles.content">            <!-- Toolbar -->            <div :class="styles.toolbar">              <div class="flex items-center gap-1 overflow-hidden h-6">                <template v-for="(crumb, idx) in breadcrumbs" :key="crumb.path">                  <span v-if="idx > 0" class="text-neutral-400 opacity-50 shrink-0 text-xs px-1"                    >/</span                  >                  <button                    class="text-xs font-semibold truncate hover:text-primary-500 hover:bg-primary-500/10 px-1.5 py-0.5 rounded transition-colors whitespace-nowrap text-neutral-700 dark:text-neutral-300"                    @click="selectedPath = crumb.path"                  >                    {{ crumb.label }}                  </button>                </template>              </div>              <div class="flex items-center gap-2 shrink-0 ml-4">                <div v-if="selectedKeys.length > 0" class="flex items-center gap-1 mr-2">                  <span class="text-xs font-bold text-primary-600 dark:text-primary-400">                    {{                      t("modals.assetManager.toolbar.selected_count", {                        count: selectedKeys.length                      })                    }}                  </span>                  <RLVButton                    icon="i-lucide-trash-2"                    size="sm"                    variant="link"                    color="error"                    @click="batchDelete"                  />                  <RLVButton                    icon="i-lucide-x"                    size="sm"                    variant="link"                    color="neutral"                    @click="selectedKeys = []"                  />                </div>                <span class="text-[10px] text-neutral-400 uppercase">                  {{ t("modals.assetManager.toolbar.items_count", { count: gridItems.length }) }}                </span>                <RLVButton                  icon="i-lucide-rotate-ccw"                  size="sm"                  variant="link"                  color="neutral"                  :loading="status === 'pending'"                  @click="refresh"                />              </div>            </div>            <!-- Loader or Empty or Grid -->            <div              v-if="status === 'pending' && !assets.length"              class="flex flex-1 items-center justify-center"            >              <span class="i-lucide-loader-2 size-8 animate-spin text-primary-500" />            </div>            <div              v-else-if="!gridItems.length"              class="flex-1 flex flex-col items-center justify-center p-12 text-center"            >              <span class="i-lucide-folder-open size-12 text-neutral-300 mb-4" />              <h3 class="text-md font-medium text-neutral-900 dark:text-white">                {{ t("modals.assetManager.empty.title") }}              </h3>              <p class="text-sm text-neutral-500 mt-1 max-w-sm">                {{ t("modals.assetManager.empty.description") }}              </p>            </div>            <div v-else class="flex-1 overflow-y-auto min-h-0">              <div :class="styles.grid">                <!-- Dropzone / Upload box inside grid -->                <div                  v-if="authPermissions.assets.canUpload.value"                  :class="styles.item"                  class="flex flex-col items-center justify-center border-dashed border-2 border-neutral-300 dark:border-neutral-700 hover:border-primary-500 cursor-pointer"                  @click="triggerFilePicker"                >                  <span class="i-lucide-upload-cloud size-8 text-neutral-400 mb-2" />                  <span class="text-xs font-semibold text-neutral-700 dark:text-neutral-300">{{                    t("modals.assetManager.upload.dropzone_label")                  }}</span>                  <span class="text-[10px] text-neutral-400 mt-0.5 text-center">{{                    t("modals.assetManager.upload.dropzone_description")                  }}</span>                </div>                <!-- Grid items -->                <div                  v-for="itemObj in gridItems"                  :key="itemObj.key"                  :class="[                    styles.item,                    dropTarget?.key === itemObj.key                      ? 'ring-2 ring-primary-500 bg-primary-500/10 scale-95'                      : ''                  ]"                  draggable="true"                  @dragstart="handleDragStart(itemObj, $event)"                  @dragover.prevent="handleDragOverFolder(itemObj, $event)"                  @drop="handleDropOnFolder(itemObj, $event)"                  @click="itemObj.type === 'folder' ? (selectedPath = itemObj.key) : null"                  class="cursor-pointer transition-all"                >                  <!-- Folder Template -->                  <template v-if="itemObj.type === 'folder'">                    <div :class="styles.preview" class="bg-primary-50/50 dark:bg-primary-900/10">                      <span class="i-lucide-folder size-12 text-primary-500/40" />                    </div>                    <div :class="styles.itemInfo">                      <span :class="styles.itemLabel">{{ itemObj.label }}</span>                      <span :class="styles.itemSize">{{                        t("modals.assetManager.item.folder_label")                      }}</span>                    </div>                  </template>                  <!-- Image / File Template -->                  <template v-else>                    <!-- Header Actions Overlay -->                    <div                      class="absolute top-2 left-0 right-0 z-20 flex items-center justify-between px-2"                    >                      <RLVCheckbox                        :model-value="selectedKeys.includes(itemObj.key)"                        @update:model-value="toggleSelection(itemObj.key)"                        @click.stop                      />                      <div class="flex items-center gap-1">                        <RLVButton                          v-if="selectionMode"                          size="sm"                          icon="i-lucide-check"                          color="primary"                          class="rounded-lg backdrop-blur-sm"                          @click.stop="emit('select', itemObj.key)"                        />                        <RLVButton                          size="sm"                          icon="i-lucide-copy"                          color="neutral"                          variant="ghost"                          class="rounded-lg backdrop-blur-sm bg-black/40 text-white"                          @click.stop="copyAssetUrl(itemObj.key)"                        />                        <RLVButton                          size="sm"                          icon="i-lucide-trash-2"                          color="error"                          variant="ghost"                          class="rounded-lg backdrop-blur-sm bg-black/40"                          @click.stop="deleteAsset(itemObj.key)"                        />                      </div>                    </div>                    <div :class="styles.preview">                      <img                        v-if="isImage(itemObj.contentType, itemObj.key)"                        :src="getAssetUrl(itemObj.key)"                        :class="styles.previewImage"                        loading="lazy"                      />                      <span v-else class="i-lucide-file size-10 text-neutral-400" />                    </div>                    <div :class="styles.itemInfo">                      <span :class="styles.itemLabel" :title="itemObj.key">{{                        itemObj.key.split("/").pop()                      }}</span>                      <div class="flex flex-col">                        <span :class="styles.itemSize" class="uppercase font-semibold">                          {{ itemObj.key.split(".").pop() }}                        </span>                        <span :class="styles.itemSize">{{ formatSize(itemObj.size) }}</span>                      </div>                    </div>                  </template>                </div>              </div>            </div>          </div>        </div>        <!-- Footer -->        <div          class="px-6 py-4 border-t border-neutral-100 dark:border-neutral-800 flex justify-between items-center shrink-0 bg-neutral-50 dark:bg-neutral-900/50"        >          <RLVButton            v-if="authPermissions.assets.canEdit.value"            variant="ghost"            icon="i-lucide-folder-plus"            :label="t('modals.assetManager.actions.new_subfolder')"            @click="triggerNewFolder"          />          <RLVButton            v-if="authPermissions.assets.canUpload.value"            icon="i-lucide-upload"            :label="t('modals.assetManager.upload.add_asset_button')"            color="primary"            @click="triggerFilePicker"          />        </div>      </div>      <input ref="fileInput" type="file" multiple class="hidden" @change="handleFileSelected" />    </div>  </teleport>  <!-- New Folder Modal -->  <teleport to="body">    <div      v-if="showNewFolderModal"      class="fixed inset-0 z-50 overflow-hidden flex items-center justify-center p-4"      role="dialog"      aria-modal="true"    >      <div        class="absolute inset-0 bg-neutral-900/60 backdrop-blur-sm"        @click="showNewFolderModal = false"      />      <div        class="bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-2xl p-6 w-full max-w-md relative z-10"      >        <h3 class="text-lg font-semibold text-neutral-900 dark:text-white">          {{ t("modals.newFolder.title") }}        </h3>        <p class="text-xs text-neutral-500 mt-1">{{ t("modals.newFolder.description") }}</p>        <div class="flex flex-col gap-4 mt-4">          <p class="text-sm text-neutral-500">            {{ t("modals.newFolder.label", { path: `/${selectedPath || "Root"}` }) }}          </p>          <RLVInput            v-model="newFolderName"            :placeholder="t('modals.newFolder.placeholder')"            autofocus            class="w-full"            @keydown.enter="confirmNewFolder"          />        </div>        <div class="flex justify-end gap-3 mt-6">          <RLVButton            :label="t('modals.newFolder.cancel_button')"            color="neutral"            variant="ghost"            @click="showNewFolderModal = false"          />          <RLVButton            :label="t('modals.newFolder.create_button')"            color="primary"            @click="confirmNewFolder"          />        </div>      </div>    </div>  </teleport>  <!-- Upload Filename Modal -->  <teleport to="body">    <div      v-if="showUploadModal"      class="fixed inset-0 z-50 overflow-hidden flex items-center justify-center p-4"      role="dialog"      aria-modal="true"    >      <div        class="absolute inset-0 bg-neutral-900/60 backdrop-blur-sm"        @click="showUploadModal = false"      />      <div        class="bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-neutral-800 shadow-2xl p-6 w-full max-w-md relative z-10"      >        <h3 class="text-lg font-semibold text-neutral-900 dark:text-white">          {{ t("modals.upload.title") }}        </h3>        <div class="flex flex-col gap-4 mt-4">          <template v-if="pendingFiles.length === 1">            <RLVFormField :label="t('modals.upload.filename_label')">              <RLVInput v-model="uploadFileBasename" class="w-full" />            </RLVFormField>          </template>          <template v-else>            <div              class="p-3 rounded-lg bg-yellow-500/10 border border-yellow-500/20 flex gap-3 items-start"            >              <span class="i-lucide-alert-triangle size-5 text-yellow-500 shrink-0 mt-0.5" />              <div class="flex flex-col">                <span class="text-xs font-bold text-yellow-600 dark:text-yellow-400">{{                  t("modals.upload.multiple_files_warning.title")                }}</span>                <p class="text-[11px] text-neutral-500 leading-relaxed">                  {{ t("modals.upload.multiple_files_warning.description") }}                </p>              </div>            </div>            <p class="text-xs font-semibold">              {{ t("modals.upload.files_selected", { count: pendingFiles.length }) }}            </p>          </template>        </div>        <div class="flex justify-end gap-3 mt-6">          <RLVButton            :label="t('modals.upload.cancel_button')"            color="neutral"            variant="ghost"            @click="showUploadModal = false"          />          <RLVButton            :label="t('modals.upload.upload_button')"            color="primary"            :loading="isProcessing"            @click="performUpload"          />        </div>      </div>    </div>  </teleport></template>